import {HQView} from './hq.js';

const DB_NAME='living-project-hq', STORE='workspace', KEY='main';
const STATUS=[['planned','Запланирована'],['doing','В работе'],['blocked','Заблокирована'],['approval','На согласовании'],['done','Выполнена']];
const PRIORITY=[['low','Низкий'],['medium','Средний'],['high','Высокий']];
const REL_TYPES=[['blocks','Блокирует'],['depends','Зависит от'],['approval','Согласование'],['related','Связано']];
const COLORS=['#7ce7d5','#76a9ff','#bb91ff','#ffc857','#ff8c8f','#8fd3ff'];
const id=()=>crypto.randomUUID?.()||Math.random().toString(36).slice(2)+Date.now().toString(36);
const esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
const iso=d=>{const x=new Date(d);x.setMinutes(x.getMinutes()-x.getTimezoneOffset());return x.toISOString().slice(0,10)};
const todayISO=()=>iso(new Date());
const addDays=(n,base=new Date())=>{const d=new Date(base);d.setDate(d.getDate()+n);return iso(d)};
const dateObj=s=>s?new Date(`${s}T12:00:00`):null;
const dayDiff=(a,b)=>Math.round((dateObj(b)-dateObj(a))/864e5);
const fmtDate=s=>s?dateObj(s).toLocaleDateString('ru-RU',{day:'2-digit',month:'short'}):'—';
const fmtLong=s=>s?dateObj(s).toLocaleDateString('ru-RU',{day:'numeric',month:'long',year:'numeric'}):'Без срока';

function starter(){
  const org=id(), personal=id(), p1=id(),p2=id(),p3=id();
  const s11=id(),s12=id(),s13=id(),s21=id(),s22=id(),s23=id(),s31=id(),s32=id();
  const tasks=[];
  const mk=(projectId,stageId,title,status,priority,start,due,assignee,description,position)=>{const t={id:id(),projectId,stageId,title,status,priority,startDate:start,dueDate:due,assignee,description,progress:status==='done'?100:status==='doing'?55:status==='approval'?80:status==='blocked'?30:10,checklist:[],position,inbox:false,createdAt:new Date().toISOString(),updatedAt:new Date().toISOString()};tasks.push(t);return t};
  const a=mk(p1,s11,'Утвердить концепцию','approval','high',addDays(-1),addDays(0),'Алия','Фиксируем финальную версию перед запуском',{x:-7.2,y:3.0});
  const b=mk(p1,s12,'Подготовить макеты','planned','high',addDays(1),addDays(2),'Дизайнер','Начинается после утверждения концепции',{x:-3.7,y:1.3});
  const c=mk(p1,s13,'Передать материалы подрядчику','planned','medium',addDays(3),addDays(4),'Мария','Финальная передача материалов',{x:-7.0,y:-1});
  const d=mk(p2,s21,'Собрать программу мероприятия','doing','high',addDays(-2),addDays(2),'Алексей','Проверить тайминг, участников и площадку',{x:4.0,y:3.0});
  const e=mk(p2,s21,'Подтвердить спикеров','approval','medium',addDays(-1),addDays(0),'Мария','Получить подтверждение участников',{x:7.2,y:1.2});
  const f=mk(p2,s22,'Печать программы','planned','medium',addDays(3),addDays(5),'Подрядчик','Запуск после финального тайминга',{x:4.2,y:-1});
  mk(p3,s31,'Подготовить аналитику за месяц','doing','medium',addDays(-2),addDays(5),'Алия','Собрать показатели и комментарии',{x:0,y:-5});
  return {
    version:4,
    meta:{demo:true,createdAt:new Date().toISOString()},
    organizations:[{id:org,name:'Рабочие проекты',color:'#7ce7d5'},{id:personal,name:'Личное',color:'#bb91ff'}],
    projects:[
      {id:p1,orgId:org,name:'Запуск кампании',status:'active',color:'#7ce7d5',description:'Подготовка и запуск коммуникационной кампании',owner:'Алия',startDate:addDays(-5),dueDate:addDays(8)},
      {id:p2,orgId:org,name:'Форум',status:'active',color:'#76a9ff',description:'Подготовка программы и проведение форума',owner:'Алексей',startDate:addDays(-8),dueDate:addDays(12)},
      {id:p3,orgId:personal,name:'Система отчётности',status:'active',color:'#bb91ff',description:'Упрощение регулярной отчётности',owner:'Алия',startDate:addDays(-3),dueDate:addDays(18)}
    ],
    stages:[
      {id:s11,projectId:p1,name:'Концепция',order:1},{id:s12,projectId:p1,name:'Производство',order:2},{id:s13,projectId:p1,name:'Запуск',order:3},
      {id:s21,projectId:p2,name:'Программа',order:1},{id:s22,projectId:p2,name:'Материалы',order:2},{id:s23,projectId:p2,name:'Проведение',order:3},
      {id:s31,projectId:p3,name:'Сбор данных',order:1},{id:s32,projectId:p3,name:'Выпуск',order:2}
    ],
    milestones:[
      {id:id(),projectId:p1,stageId:s11,title:'Концепция утверждена',dueDate:addDays(0),done:false},
      {id:id(),projectId:p1,stageId:s13,title:'Кампания запущена',dueDate:addDays(8),done:false},
      {id:id(),projectId:p2,stageId:s21,title:'Программа зафиксирована',dueDate:addDays(2),done:false},
      {id:id(),projectId:p2,stageId:s23,title:'Форум проведён',dueDate:addDays(12),done:false}
    ],
    tasks,
    relations:[
      {id:id(),sourceId:a.id,targetId:b.id,type:'blocks'},
      {id:id(),sourceId:b.id,targetId:c.id,type:'blocks'},
      {id:id(),sourceId:e.id,targetId:d.id,type:'blocks'},
      {id:id(),sourceId:d.id,targetId:f.id,type:'blocks'}
    ]
  };
}

function normalizeState(raw){
  const s=raw&&typeof raw==='object'?raw:starter();
  const knownDemo=!s.meta&&['Запуск кампании','Форум','Система отчётности'].every(name=>s.projects?.some(p=>p.name===name));
  s.version=5;s.meta=s.meta||{demo:knownDemo};s.organizations=s.organizations||[];s.projects=s.projects||[];s.tasks=s.tasks||[];s.relations=s.relations||[];s.stages=s.stages||[];s.milestones=s.milestones||[];
  if(!s.organizations.length)s.organizations.push({id:id(),name:'Рабочие проекты',color:COLORS[0]});
  for(const [i,p] of s.projects.entries()){
    p.description??='';p.owner??='';p.members??=[];p.startDate??='';p.dueDate??='';p.color??=COLORS[i%COLORS.length];p.status??='active';p.archived??=false;
    let stages=s.stages.filter(x=>x.projectId===p.id);
    if(!stages.length){stages=[{id:id(),projectId:p.id,name:'Подготовка',order:1},{id:id(),projectId:p.id,name:'Реализация',order:2},{id:id(),projectId:p.id,name:'Завершение',order:3}];s.stages.push(...stages)}
    for(const t of s.tasks.filter(x=>x.projectId===p.id)){t.stageId??=stages[0]?.id||''}
  }
  for(const t of s.tasks){t.startDate??='';t.dueDate??='';t.description??='';t.assignee??='';t.status??='planned';t.priority??='medium';t.progress??=0;t.checklist??=[];t.position??=null;t.inbox=!!t.inbox||!t.projectId}
  return s;
}

let dbPromise;
function db(){return dbPromise||(dbPromise=new Promise((resolve,reject)=>{const r=indexedDB.open(DB_NAME,1);r.onupgradeneeded=()=>{if(!r.result.objectStoreNames.contains(STORE))r.result.createObjectStore(STORE)};r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)}))}
async function loadState(){try{const d=await db();const value=await new Promise((res,rej)=>{const tx=d.transaction(STORE,'readonly'),r=tx.objectStore(STORE).get(KEY);r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error)});return normalizeState(value||starter())}catch(e){console.warn('IndexedDB unavailable',e);return starter()}}
async function persist(){try{const d=await db();await new Promise((res,rej)=>{const tx=d.transaction(STORE,'readwrite');tx.objectStore(STORE).put(state,KEY);tx.oncomplete=()=>res();tx.onerror=()=>rej(tx.error)})}catch(e){console.warn(e)}}

let state=await loadState();
let view='home',calendarMode='month',scope='all',currentProject='all',selectedTaskId=null,selectedProjectId=null,search='',hq=null,saveTimer=null,monthAnchor=new Date(),timelineStart=new Date();
const initialHash=new URLSearchParams(location.hash.replace(/^#/,''));
if(['home','board','list','kanban','calendar','people','hq'].includes(initialHash.get('view')))view=initialHash.get('view');
if(initialHash.get('project')&&state.projects.some(p=>p.id===initialHash.get('project')))currentProject=initialHash.get('project');
if(initialHash.get('task')&&state.tasks.some(t=>t.id===initialHash.get('task')))selectedTaskId=initialHash.get('task');
if(initialHash.get('focus')&&state.projects.some(p=>p.id===initialHash.get('focus')))selectedProjectId=initialHash.get('focus');
timelineStart.setHours(12,0,0,0);timelineStart.setDate(timelineStart.getDate()-3);
const app=document.querySelector('#app');
const projectBy=x=>state.projects.find(p=>p.id===x), taskBy=x=>state.tasks.find(t=>t.id===x), stageBy=x=>state.stages.find(s=>s.id===x);
const statusName=v=>STATUS.find(x=>x[0]===v)?.[1]||v, priorityName=v=>PRIORITY.find(x=>x[0]===v)?.[1]||v;
const projectStages=p=>state.stages.filter(s=>s.projectId===p).sort((a,b)=>a.order-b.order);
const projectTasks=p=>state.tasks.filter(t=>t.projectId===p);
const projectMilestones=p=>state.milestones.filter(m=>m.projectId===p).sort((a,b)=>(a.dueDate||'9999').localeCompare(b.dueDate||'9999'));
function isOverdue(t){return !!t.dueDate&&effectiveStatus(t)!=='done'&&dateObj(t.dueDate)<new Date(new Date().setHours(0,0,0,0))}
function predecessors(t){const ids=[];for(const r of state.relations){if(r.type==='blocks'&&r.targetId===t.id)ids.push(r.sourceId);if(r.type==='depends'&&r.sourceId===t.id)ids.push(r.targetId)}return ids.map(taskBy).filter(Boolean)}
function autoBlockers(t){if(t.status==='done')return[];return predecessors(t).filter(p=>effectiveStatusBase(p)!=='done')}
function effectiveStatusBase(t){return t?.status||'planned'}
function effectiveStatus(t){if(!t)return'planned';if(t.status==='done')return'done';if(t.status==='blocked')return'blocked';return autoBlockers(t).length?'blocked':t.status}
function isRisk(t){const st=effectiveStatus(t);return st==='blocked'||isOverdue(t)||(t.priority==='high'&&st!=='done'&&t.dueDate&&dateObj(t.dueDate)-Date.now()<3*864e5)}
function projectProgress(p){const a=projectTasks(p);return a.length?Math.round(a.reduce((n,t)=>n+(effectiveStatus(t)==='done'?100:Number(t.progress||0)),0)/a.length):0}
function projectRiskCount(p){return projectTasks(p).filter(isRisk).length}
function word(n,one,few,many){const a=Math.abs(n)%100,b=a%10;return a>10&&a<20?many:b===1?one:b>1&&b<5?few:many}
function setSaveState(text='Сохранено'){const el=document.querySelector('#saveState');if(el)el.textContent=text}
function scheduleSave(){clearTimeout(saveTimer);setSaveState('Сохраняю…');saveTimer=setTimeout(async()=>{await persist();setSaveState('Сохранено')},150)}
function toast(msg,action){document.querySelector('.toast')?.remove();const el=document.createElement('div');el.className='toast';el.innerHTML=`<span>${esc(msg)}</span>${action?'<button>Отменить</button>':''}`;document.body.appendChild(el);if(action)el.querySelector('button').onclick=()=>{action();el.remove()};setTimeout(()=>el.remove(),action?5000:2200)}
function updateUrl(){const q=new URLSearchParams;if(view!=='home')q.set('view',view);if(currentProject!=='all')q.set('project',currentProject);if(selectedTaskId)q.set('task',selectedTaskId);else if(selectedProjectId)q.set('focus',selectedProjectId);history.replaceState(null,'',q.size?`#${q}`:location.pathname+location.search)}
function setView(next){view=next;document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));renderMain();renderInspector();updateUrl()}
function supportsWebGL(){try{const c=document.createElement('canvas');return !!(c.getContext('webgl2')||c.getContext('webgl'))}catch{return false}}

function dependencyEdges(projectId){
  const ids=new Set(projectTasks(projectId).map(t=>t.id)), edges=[];
  for(const r of state.relations){if(!ids.has(r.sourceId)||!ids.has(r.targetId))continue;if(r.type==='blocks')edges.push([r.sourceId,r.targetId]);else if(r.type==='depends')edges.push([r.targetId,r.sourceId])}
  return edges;
}
function taskWeight(t){if(t.startDate&&t.dueDate)return Math.max(1,dayDiff(t.startDate,t.dueDate)+1);return 1}
function criticalPath(projectId){
  const tasks=projectTasks(projectId), by=new Map(tasks.map(t=>[t.id,t])), out=new Map(tasks.map(t=>[t.id,[]]));
  for(const [a,b] of dependencyEdges(projectId))out.get(a)?.push(b);
  const memo=new Map(), visiting=new Set();
  const dfs=node=>{if(memo.has(node))return memo.get(node);if(visiting.has(node))return{score:0,path:[]};visiting.add(node);let best={score:0,path:[]};for(const nx of out.get(node)||[]){const r=dfs(nx);if(r.score>best.score)best=r}visiting.delete(node);const res={score:taskWeight(by.get(node))+(best.score||0),path:[node,...best.path]};memo.set(node,res);return res};
  let best={score:0,path:[]};for(const t of tasks){const r=dfs(t.id);if(r.score>best.score)best=r}return best.path;
}
function allCriticalIds(){const set=new Set();for(const p of state.projects)criticalPath(p.id).forEach(x=>set.add(x));return set}

function filteredTasks(){
  let items=[...state.tasks];
  if(currentProject==='inbox')items=items.filter(t=>!t.projectId||t.inbox);
  else{items=items.filter(t=>t.projectId);if(currentProject!=='all')items=items.filter(t=>t.projectId===currentProject)}
  if(scope==='today')items=items.filter(t=>t.dueDate===todayISO()||isOverdue(t)||effectiveStatus(t)==='approval');
  if(scope==='week'){const end=addDays(7);items=items.filter(t=>(t.dueDate&&t.dueDate>=todayISO()&&t.dueDate<=end)||isOverdue(t))}
  if(scope==='risks')items=items.filter(isRisk);
  if(scope==='approval')items=items.filter(t=>effectiveStatus(t)==='approval');
  if(scope==='critical'){const ids=allCriticalIds();items=items.filter(t=>ids.has(t.id))}
  if(search){const q=search.toLowerCase();items=items.filter(t=>`${t.title} ${t.description} ${t.assignee} ${projectBy(t.projectId)?.name||''} ${stageBy(t.stageId)?.name||''}`.toLowerCase().includes(q))}
  return items;
}
function updateTask(taskId,patch){const t=taskBy(taskId);if(!t)return;const next={...t,...patch};if(next.startDate&&next.dueDate&&next.dueDate<next.startDate){toast('Срок не может быть раньше даты начала');renderInspector();return}Object.assign(t,patch,{updatedAt:new Date().toISOString()});if(patch.projectId!==undefined)t.inbox=!patch.projectId;scheduleSave();renderMain();renderSidebar();renderInspector();}
function addTask(data,{quick=false}={}){const p=projectBy(data.projectId);const t={id:id(),title:data.title||'Новая задача',description:data.description||'',projectId:p?.id||'',stageId:data.stageId||projectStages(p?.id)[0]?.id||'',status:data.status||'planned',priority:data.priority||'medium',startDate:data.startDate||'',dueDate:data.dueDate||'',assignee:data.assignee||'',progress:0,checklist:[],position:null,inbox:!p,createdAt:new Date().toISOString(),updatedAt:new Date().toISOString()};state.tasks.unshift(t);selectedTaskId=t.id;selectedProjectId=null;scheduleSave();renderAll(true);toast(quick?'Добавлено во Входящие':'Задача создана')}
function deleteTask(taskId){const task=taskBy(taskId),rels=state.relations.filter(r=>r.sourceId===taskId||r.targetId===taskId);if(!task||!confirm(`Удалить задачу «${task.title}»?`))return;state.tasks=state.tasks.filter(t=>t.id!==taskId);state.relations=state.relations.filter(r=>r.sourceId!==taskId&&r.targetId!==taskId);if(selectedTaskId===taskId)selectedTaskId=null;scheduleSave();renderAll(false);toast('Задача удалена',()=>{state.tasks.unshift(task);state.relations.push(...rels);scheduleSave();renderAll(false)})}
function deleteProject(projectId){const project=projectBy(projectId);if(!project||!confirm(`Удалить проект «${project.name}» вместе с его задачами?`))return;const pack={project,tasks:projectTasks(projectId),stages:projectStages(projectId),milestones:projectMilestones(projectId)},taskIds=new Set(pack.tasks.map(t=>t.id));pack.relations=state.relations.filter(r=>taskIds.has(r.sourceId)||taskIds.has(r.targetId));state.projects=state.projects.filter(p=>p.id!==projectId);state.tasks=state.tasks.filter(t=>t.projectId!==projectId);state.stages=state.stages.filter(s=>s.projectId!==projectId);state.milestones=state.milestones.filter(m=>m.projectId!==projectId);state.relations=state.relations.filter(r=>!taskIds.has(r.sourceId)&&!taskIds.has(r.targetId));currentProject='all';selectedProjectId=null;selectedTaskId=null;scheduleSave();renderAll(false);toast('Проект удалён',()=>{state.projects.push(pack.project);state.tasks.push(...pack.tasks);state.stages.push(...pack.stages);state.milestones.push(...pack.milestones);state.relations.push(...pack.relations);scheduleSave();renderAll(false)})}
function duplicateProject(projectId){const source=projectBy(projectId);if(!source)return;const pid=id(),now=new Date().toISOString(),stageMap=new Map(),taskMap=new Map();const copy={...source,id:pid,name:`${source.name} — копия`,archived:false,createdAt:now,updatedAt:now,members:[...(source.members||[])]};state.projects.push(copy);for(const stage of projectStages(projectId)){const next={...stage,id:id(),projectId:pid};stageMap.set(stage.id,next.id);state.stages.push(next)}for(const task of projectTasks(projectId)){const next={...task,id:id(),projectId:pid,stageId:stageMap.get(task.stageId)||'',checklist:(task.checklist||[]).map(x=>({...x})),position:null,createdAt:now,updatedAt:now};taskMap.set(task.id,next.id);state.tasks.push(next)}for(const milestone of projectMilestones(projectId))state.milestones.push({...milestone,id:id(),projectId:pid,stageId:stageMap.get(milestone.stageId)||''});for(const relation of state.relations.filter(r=>taskMap.has(r.sourceId)&&taskMap.has(r.targetId)))state.relations.push({...relation,id:id(),sourceId:taskMap.get(relation.sourceId),targetId:taskMap.get(relation.targetId)});currentProject=pid;scope='all';selectedProjectId=pid;selectedTaskId=null;scheduleSave();renderAll(false);toast('Проект скопирован')}
function addRelation(a,b,type='blocks'){if(a===b||state.relations.some(r=>r.sourceId===a&&r.targetId===b&&r.type===type))return;state.relations.push({id:id(),sourceId:a,targetId:b,type});scheduleSave();renderInspector();renderMain();toast('Связь создана')}

function shell(){
  app.innerHTML=`<div class="app-shell"><header class="topbar"><div class="brand"><div class="mark"></div><div><strong>LIVING PROJECT HQ</strong><small>визуальный штаб проектов</small></div></div><nav class="view-tabs" aria-label="Режим просмотра">${[['home','Обзор'],['board','Доска'],['list','Список'],['kanban','Kanban'],['calendar','Календарь'],['people','Люди'],['hq','Связи']].map(([v,n])=>`<button class="tab ${view===v?'active':''}" data-view="${v}">${n}</button>`).join('')}</nav><div class="top-search"><input id="search" aria-label="Поиск" placeholder="Поиск задач, проектов, людей…" value="${esc(search)}"></div><span class="save-state" id="saveState">Сохранено</span><div class="top-actions"><button class="btn ghost" id="quickInbox">+ Входящие</button><button class="btn ghost" id="newProject">+ Проект</button><button class="btn ghost" id="dataMenu">Данные</button><button class="btn mobile-menu-btn" id="mobileMenu" aria-label="Открыть меню">Меню</button><button class="btn primary" id="newTask">+ Задача</button></div></header><aside class="sidebar" id="sidebar"></aside><main class="main" id="main"></main><aside class="inspector" id="inspector"></aside></div>`;
  document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>setView(b.dataset.view));
  document.querySelector('#search').oninput=e=>{search=e.target.value;renderMain()};
  document.querySelector('#quickInbox').onclick=openQuickModal;document.querySelector('#newTask').onclick=openTaskModal;document.querySelector('#newProject').onclick=openProjectModal;document.querySelector('#dataMenu').onclick=openDataModal;document.querySelector('#mobileMenu').onclick=openMobileMenu;
}
function renderSidebar(){
  const el=document.querySelector('#sidebar');if(!el)return;
  const inbox=state.tasks.filter(t=>!t.projectId||t.inbox).length;
  const activeProjects=state.projects.filter(p=>!p.archived);
  let html=`<div class="side-title"><b>Пространство</b><button class="icon-btn" id="newOrg" aria-label="Управление пространствами" title="Управление пространствами">⚙</button></div><div class="tree"><div class="project-link ${currentProject==='inbox'?'active':''}" data-project="inbox" role="button" tabindex="0"><span>📥 Входящие</span><span class="count-pill">${inbox}</span></div><div class="project-link all-projects ${currentProject==='all'?'active':''}" data-project="all" role="button" tabindex="0"><span>Все проекты</span><span class="count-pill">${activeProjects.length}</span></div>`;
  for(const org of state.organizations){const ps=activeProjects.filter(p=>p.orgId===org.id);html+=`<div class="org"><div class="org-head"><span class="dot" style="background:${org.color||COLORS[0]}"></span>${esc(org.name)}</div>${ps.map(p=>`<div class="project-link ${currentProject===p.id?'active':''}" data-project="${p.id}" role="button" tabindex="0"><span>${esc(p.name)}</span><span class="count-pill">${projectRiskCount(p.id)?`⚠ ${projectRiskCount(p.id)}`:projectTasks(p.id).length}</span></div>`).join('')}</div>`}
  html+=`</div><div class="side-sep"></div><div class="filter-set">${[['all','Все задачи'],['today','Сегодня'],['week','Неделя'],['risks','Риски'],['approval','Ждут решения'],['critical','Критический путь']].map(([v,n])=>`<button class="filter-btn ${scope===v?'active':''}" data-scope="${v}">${n}</button>`).join('')}</div>`;
  el.innerHTML=html;
  el.querySelectorAll('[data-project]').forEach(x=>{const go=()=>{currentProject=x.dataset.project;scope='all';selectedTaskId=null;selectedProjectId=(currentProject!=='all'&&currentProject!=='inbox')?currentProject:null;renderAll(false);updateUrl()};x.onclick=go;x.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();go()}}});
  el.querySelectorAll('[data-scope]').forEach(x=>x.onclick=()=>{scope=x.dataset.scope;renderAll(false);updateUrl()});el.querySelector('#newOrg').onclick=openOrgModal;
}
function summary(items){return{today:items.filter(t=>t.dueDate===todayISO()&&effectiveStatus(t)!=='done').length,overdue:items.filter(isOverdue).length,approval:items.filter(t=>effectiveStatus(t)==='approval').length,blocked:items.filter(t=>effectiveStatus(t)==='blocked').length}}
function pageTitle(){if(currentProject==='inbox')return'Входящие';if(currentProject!=='all')return projectBy(currentProject)?.name||'Проект';if(scope==='today')return'Сегодня';if(scope==='week')return'Неделя';if(scope==='risks')return'Риски';if(scope==='approval')return'Ждут решения';if(scope==='critical')return'Критический путь';return'Все проекты'}
function contextName(){if(currentProject==='inbox')return'Входящие';if(currentProject!=='all')return projectBy(currentProject)?.name||'Проект';return'Все проекты'}
function contextBar(main){if(view==='board')return;const names={today:'Сегодня и просроченные',week:'Ближайшие 7 дней',risks:'Риски',approval:'Ждут решения',critical:'Критический путь'};const active=currentProject!=='all'||scope!=='all'||!!search;if(!active)return;const bar=document.createElement('div');bar.className='context-bar';bar.innerHTML=`<span>Показано:</span><b>${esc(contextName())}</b>${scope!=='all'?`<b>${esc(names[scope]||scope)}</b>`:''}${search?`<b>Поиск: ${esc(search)}</b>`:''}<button class="btn mini" data-reset-context>Сбросить</button>`;main.prepend(bar);bar.querySelector('[data-reset-context]').onclick=()=>{currentProject='all';scope='all';search='';selectedTaskId=null;selectedProjectId=null;document.querySelector('#search').value='';renderAll(false);updateUrl()}}
function renderMain(){const main=document.querySelector('#main');if(!main)return;if(hq){hq.destroy();hq=null}if(view==='board'){main.innerHTML='<div class="loading-state">Открываю доску…</div>';window.dispatchEvent(new CustomEvent('living-hq:open-board'));return}const items=filteredTasks();if(view==='home')renderHome(main,items);else if(view==='list')renderList(main,items);else if(view==='kanban')renderKanban(main,items);else if(view==='calendar')renderCalendar(main,items);else if(view==='people')renderPeople(main,items);else renderHQ(main,items);contextBar(main)}
function taskStatusChip(t){const st=effectiveStatus(t),auto=st==='blocked'&&t.status!=='blocked';return`<span class="status-chip status-${st}">${statusName(st)}${auto?' · авто':''}</span>`}
function nextAction(p){const tasks=projectTasks(p.id).filter(t=>effectiveStatus(t)!=='done').sort((a,b)=>{const ar=isRisk(a)?0:1,br=isRisk(b)?0:1;return ar-br||(a.dueDate||'9999').localeCompare(b.dueDate||'9999')});return tasks[0]}
function renderHome(main,items){
  const open=items.filter(t=>effectiveStatus(t)!=='done'), risks=open.filter(isRisk), approvals=open.filter(t=>effectiveStatus(t)==='approval'), today=open.filter(t=>t.dueDate===todayISO()||isOverdue(t));
  const q=search.toLowerCase();const projects=state.projects.filter(p=>!p.archived&&(currentProject==='all'||p.id===currentProject)&&(!q||`${p.name} ${p.description} ${p.owner} ${(p.members||[]).join(' ')} ${projectTasks(p.id).map(t=>`${t.title} ${t.description} ${t.assignee}`).join(' ')}`.toLowerCase().includes(q))).map(p=>({p,risk:projectRiskCount(p.id),next:nextAction(p)})).sort((a,b)=>b.risk-a.risk||(a.p.dueDate||'9999').localeCompare(b.p.dueDate||'9999'));
  const taskList=(list,empty)=>list.slice(0,6).map(t=>`<button class="home-task" data-task="${t.id}"><span><b>${esc(t.title)}</b><small>${esc(projectBy(t.projectId)?.name||'Входящие')} · ${esc(t.assignee||'без ответственного')}</small></span><em class="${isOverdue(t)?'overdue':''}">${fmtDate(t.dueDate)}</em></button>`).join('')||`<div class="home-empty">${empty}</div>`;
  main.innerHTML=`<div class="main-scroll home-page">${state.meta?.demo?`<div class="demo-banner"><div><b>Это демонстрационное пространство</b><span>Можно изучить пример или начать со своих проектов.</span></div><button class="btn" data-keep-demo>Оставить пример</button><button class="btn primary" data-clean-start>Начать с чистого листа</button></div>`:''}<div class="page-head"><div><div class="eyebrow">${currentProject==='all'?'Командный обзор':'Обзор проекта'}</div><h1>${currentProject==='all'?'Что требует внимания':esc(contextName())}</h1><p>Сегодняшние действия, риски и состояние проектов — без лишних переходов.</p></div><button class="btn primary" id="homeQuick">+ Быстрая задача</button></div><div class="home-kpis"><button data-home-scope="today"><span>Сегодня</span><strong>${today.length}</strong><small>включая просроченные</small></button><button data-home-scope="risks" title="Риск: просрочка, блокировка или задача высокого приоритета со сроком в ближайшие три дня"><span>Риски</span><strong>${risks.length}</strong><small>просрочки, блокеры и срочные</small></button><button data-home-scope="approval"><span>Ждут решения</span><strong>${approvals.length}</strong><small>на согласовании</small></button><button data-home-scope="all"><span>Открыто</span><strong>${open.length}</strong><small>${word(open.length,'активная задача','активные задачи','активных задач')}</small></button></div><div class="home-grid"><section class="home-panel"><div class="home-panel-head"><div><span class="eyebrow">Фокус дня</span><h2>Сделать сейчас</h2></div></div>${taskList(today,'На сегодня срочных задач нет')}</section><section class="home-panel"><div class="home-panel-head"><div><span class="eyebrow">Контроль</span><h2>Риски и блокеры</h2></div></div>${taskList(risks,'Открытых рисков нет')}</section></div><section class="home-panel project-pulse"><div class="home-panel-head"><div><span class="eyebrow">${currentProject==='all'?'Портфель':'Проект'}</span><h2>${currentProject==='all'?'Состояние проектов':'Состояние проекта'}</h2></div></div><div class="project-pulse-grid">${projects.map(({p,risk,next})=>`<button class="project-pulse-card" data-project-open="${p.id}"><div class="pulse-top"><span class="dot" style="background:${p.color}"></span><b>${esc(p.name)}</b><em class="${risk?'risk':''}">${risk?`⚠ ${risk}`:'Стабильно'}</em></div><div class="pulse-progress"><i style="width:${projectProgress(p.id)}%"></i></div><div class="pulse-meta"><span>${projectProgress(p.id)}% готово</span><span>${fmtDate(p.dueDate)}</span></div><div class="pulse-next"><small>Следующее действие</small><strong>${esc(next?.title||'Определить следующий шаг')}</strong></div></button>`).join('')||'<div class="home-empty">Ничего не найдено</div>'}</div></section></div>`;
  main.querySelector('#homeQuick').onclick=openQuickModal;main.querySelectorAll('[data-task]').forEach(x=>x.onclick=()=>{selectedTaskId=x.dataset.task;selectedProjectId=null;renderInspector()});main.querySelectorAll('[data-project-open]').forEach(x=>x.onclick=()=>{selectedProjectId=x.dataset.projectOpen;selectedTaskId=null;renderInspector()});main.querySelectorAll('[data-home-scope]').forEach(x=>x.onclick=()=>{scope=x.dataset.homeScope;view='list';renderAll(true)})
  main.querySelector('[data-keep-demo]')?.addEventListener('click',()=>{state.meta.demo=false;scheduleSave();renderMain()});main.querySelector('[data-clean-start]')?.addEventListener('click',startClean)
}
function renderPeople(main,items){
  const names=[...new Set(items.map(t=>t.assignee?.trim()||'Без ответственного'))].sort((a,b)=>a.localeCompare(b,'ru'));
  main.innerHTML=`<div class="main-scroll people-page"><div class="page-head"><div><div class="eyebrow">Команда</div><h1>Люди и загрузка</h1><p>У кого много задач, где появились риски и что ждёт решения.</p></div></div><div class="people-grid">${names.map(name=>{const ts=items.filter(t=>(t.assignee?.trim()||'Без ответственного')===name),open=ts.filter(t=>effectiveStatus(t)!=='done'),risk=open.filter(isRisk),approval=open.filter(t=>effectiveStatus(t)==='approval'),load=Math.min(100,open.reduce((n,t)=>n+(t.priority==='high'?25:t.priority==='medium'?16:10),0));return`<article class="person-card"><div class="person-head"><div class="person-avatar">${esc(name.slice(0,1).toUpperCase())}</div><div><h2>${esc(name)}</h2><p>${open.length} ${word(open.length,'активная','активные','активных')} · ${risk.length} ${word(risk.length,'риск','риска','рисков')}</p></div></div><div class="person-load"><span>Загрузка</span><b>${load}%</b><i><em style="width:${load}%"></em></i></div><div class="person-stats"><span><b>${ts.filter(t=>t.dueDate===todayISO()).length}</b> сегодня</span><span><b>${approval.length}</b> решений</span><span><b>${risk.length}</b> рисков</span></div><div class="person-tasks">${open.sort((a,b)=>(a.dueDate||'9999').localeCompare(b.dueDate||'9999')).slice(0,3).map(t=>`<button data-task="${t.id}"><span>${esc(t.title)}</span><small class="${isOverdue(t)?'overdue':''}">${fmtDate(t.dueDate)}</small></button>`).join('')||'<small>Все задачи завершены</small>'}</div></article>`}).join('')||'<div class="empty-state"><h3>Пока нет исполнителей</h3><p>Назначьте ответственных в карточках задач.</p></div>'}</div></div>`;
  main.querySelectorAll('[data-task]').forEach(x=>x.onclick=()=>{selectedTaskId=x.dataset.task;selectedProjectId=null;renderInspector()})
}
function renderList(main,items){const s=summary(items);main.innerHTML=`<div class="main-scroll"><div class="page-head"><div><h1>${esc(pageTitle())}</h1><p>${currentProject==='inbox'?'Быстро зафиксируйте задачу, проект назначите позже':'Единое пространство задач, этапов, сроков и зависимостей'}</p></div>${currentProject==='inbox'?'<button class="btn primary" id="captureHere">+ Быстро добавить</button>':''}</div><div class="summary-grid"><div class="summary"><span>Сегодня</span><strong>${s.today}</strong><em>срок сегодня</em></div><div class="summary"><span>Просрочено</span><strong>${s.overdue}</strong><em>требуют внимания</em></div><div class="summary"><span>Согласование</span><strong>${s.approval}</strong><em>ждут решения</em></div><div class="summary"><span>Заблокировано</span><strong>${s.blocked}</strong><em>включая автоблокировки</em></div></div>${items.length?`<div class="table-wrap"><table class="task-table"><thead><tr><th>Задача</th><th>Этап</th><th>Статус</th><th>Ответственный</th><th>Срок</th><th>Приоритет</th></tr></thead><tbody>${items.map(t=>`<tr data-task="${t.id}"><td><div class="task-title">${esc(t.title)}</div><div class="task-sub">${esc(projectBy(t.projectId)?.name||'Входящие')}</div></td><td>${esc(stageBy(t.stageId)?.name||'—')}</td><td>${taskStatusChip(t)}</td><td>${esc(t.assignee||'—')}</td><td class="${isOverdue(t)?'overdue':''}">${fmtDate(t.dueDate)}</td><td><span class="priority-chip priority-${t.priority}">${priorityName(t.priority)}</span></td></tr>`).join('')}</tbody></table></div>`:`<div class="empty-state"><h3>Здесь пока пусто</h3><p>${currentProject==='inbox'?'Бросьте сюда мысль или поручение — разберёте позже.':'Создайте задачу или измените фильтр.'}</p></div>`}</div>`;
  main.querySelectorAll('[data-task]').forEach(r=>r.onclick=()=>{selectedTaskId=r.dataset.task;selectedProjectId=null;renderInspector()});main.querySelector('#captureHere')?.addEventListener('click',openQuickModal)
}
function renderKanban(main,items){main.innerHTML=`<div class="main-scroll"><div class="page-head"><div><h1>${esc(pageTitle())}</h1><p>Перетаскивайте карточки между рабочими статусами</p></div></div><div class="kanban">${STATUS.map(([st,name])=>`<section class="kan-col" data-col="${st}"><div class="kan-head"><span>${name}</span><span class="count-pill">${items.filter(t=>effectiveStatus(t)===st).length}</span></div>${items.filter(t=>effectiveStatus(t)===st).map(t=>`<article class="kan-card ${t.status!==st&&st==='blocked'?'auto-blocked-card':''}" draggable="true" data-task="${t.id}"><h3>${esc(t.title)}</h3><div class="task-sub">${esc(stageBy(t.stageId)?.name||projectBy(t.projectId)?.name||'Входящие')}</div><div class="kan-meta"><span>${esc(t.assignee||'Без ответственного')}</span><span class="${isOverdue(t)?'overdue':''}">${fmtDate(t.dueDate)}</span></div></article>`).join('')}</section>`).join('')}</div></div>`;
  main.querySelectorAll('.kan-card').forEach(c=>{c.ondragstart=e=>{e.dataTransfer.setData('text/plain',c.dataset.task);setTimeout(()=>c.style.opacity=.35,0)};c.ondragend=()=>c.style.opacity=1;c.onclick=()=>{selectedTaskId=c.dataset.task;selectedProjectId=null;renderInspector()}});main.querySelectorAll('.kan-col').forEach(col=>{col.ondragover=e=>{e.preventDefault();col.classList.add('drag-over')};col.ondragleave=()=>col.classList.remove('drag-over');col.ondrop=e=>{e.preventDefault();col.classList.remove('drag-over');const tid=e.dataTransfer.getData('text/plain');if(col.dataset.col!=='blocked'&&autoBlockers(taskBy(tid)).length){toast('Сначала завершите блокирующие задачи');return}updateTask(tid,{status:col.dataset.col})}})
}

function renderCalendar(main,items){
  main.innerHTML=`<div class="main-scroll calendar-page"><div class="page-head"><div><h1>Календарь и Timeline</h1><p>Сроки задач, этапы и ключевые вехи проектов</p></div><div class="segmented"><button class="btn ${calendarMode==='month'?'active':''}" data-calmode="month">Месяц</button><button class="btn ${calendarMode==='timeline'?'active':''}" data-calmode="timeline">Timeline</button></div></div><div id="calendarBody"></div></div>`;
  main.querySelectorAll('[data-calmode]').forEach(b=>b.onclick=()=>{calendarMode=b.dataset.calmode;renderCalendar(main,items)});calendarMode==='month'?renderMonth(main.querySelector('#calendarBody'),items):renderTimeline(main.querySelector('#calendarBody'),items)
}
function renderMonth(el,items){
  const a=new Date(monthAnchor);a.setDate(1);a.setHours(12,0,0,0);const start=new Date(a);const dow=(start.getDay()+6)%7;start.setDate(start.getDate()-dow);const monthName=a.toLocaleDateString('ru-RU',{month:'long',year:'numeric'});const visibleProjects=new Set(items.map(t=>t.projectId));const milestones=state.milestones.filter(m=>(currentProject==='all'||m.projectId===currentProject)&&(!visibleProjects.size||visibleProjects.has(m.projectId)));
  let html=`<div class="calendar-nav"><button class="btn" data-calnav="-1">←</button><strong>${monthName}</strong><button class="btn" data-calnav="1">→</button><button class="btn ghost" data-calnav="0">Сегодня</button></div><div class="month-grid">${['Пн','Вт','Ср','Чт','Пт','Сб','Вс'].map(d=>`<div class="dow">${d}</div>`).join('')}`;
  for(let i=0;i<42;i++){const d=new Date(start);d.setDate(start.getDate()+i);const ds=iso(d),inMonth=d.getMonth()===a.getMonth(),dayTasks=items.filter(t=>t.dueDate===ds),dayMs=milestones.filter(m=>m.dueDate===ds);html+=`<div class="day-cell ${inMonth?'':'outside'} ${ds===todayISO()?'today-cell':''}"><div class="day-num">${d.getDate()}</div>${dayMs.map(m=>`<button class="milestone-chip" data-project-open="${m.projectId}" title="Веха">◆ ${esc(m.title)}</button>`).join('')}${dayTasks.slice(0,4).map(t=>`<button class="cal-task status-border-${effectiveStatus(t)}" data-task="${t.id}">${esc(t.title)}</button>`).join('')}${dayTasks.length>4?`<small>+ ещё ${dayTasks.length-4}</small>`:''}</div>`}html+='</div>';el.innerHTML=html;
  el.querySelectorAll('[data-calnav]').forEach(b=>b.onclick=()=>{const n=Number(b.dataset.calnav);if(n===0)monthAnchor=new Date();else monthAnchor.setMonth(monthAnchor.getMonth()+n);renderMonth(el,items)});el.querySelectorAll('[data-task]').forEach(b=>b.onclick=()=>{selectedTaskId=b.dataset.task;selectedProjectId=null;renderInspector()});el.querySelectorAll('[data-project-open]').forEach(b=>b.onclick=()=>{selectedProjectId=b.dataset.projectOpen;selectedTaskId=null;renderInspector()})
}
function renderTimeline(el,items){
  const days=21,start=new Date(timelineStart);const dates=Array.from({length:days},(_,i)=>{const d=new Date(start);d.setDate(d.getDate()+i);return d});
  const projectIds=currentProject==='all'?[...new Set(items.map(t=>t.projectId).filter(Boolean))]:[currentProject].filter(x=>x!=='inbox');
  let html=`<div class="calendar-nav"><button class="btn" data-tlnav="-7">← 7 дней</button><button class="btn ghost" data-tlnav="0">Сегодня</button><button class="btn" data-tlnav="7">7 дней →</button></div><div class="timeline" style="--days:${days}"><div class="timeline-head"><div class="tl-label">Проект / задача</div>${dates.map(d=>`<div class="tl-day ${iso(d)===todayISO()?'tl-today':''}"><b>${d.getDate()}</b><small>${d.toLocaleDateString('ru-RU',{weekday:'short'})}</small></div>`).join('')}</div>`;
  for(const pid of projectIds){const p=projectBy(pid);const pTasks=items.filter(t=>t.projectId===pid);if(!p)continue;html+=`<div class="tl-project"><div class="tl-project-title" data-project-open="${pid}">${esc(p.name)} <span>${projectProgress(pid)}%</span></div></div>`;for(const t of pTasks){const s=t.startDate||t.dueDate,e=t.dueDate||t.startDate;if(!s&&!e)continue;const startIdx=Math.max(0,dayDiff(iso(start),s)),endIdx=Math.min(days-1,dayDiff(iso(start),e));if(endIdx<0||startIdx>=days)continue;const left=startIdx+1,width=Math.max(1,endIdx-startIdx+1);html+=`<div class="tl-row"><button class="tl-label tl-task-label" data-task="${t.id}">${esc(t.title)}</button><div class="tl-track">${dates.map(d=>`<span class="${iso(d)===todayISO()?'tl-today-bg':''}"></span>`).join('')}<button class="tl-bar status-bg-${effectiveStatus(t)}" data-task="${t.id}" style="--start:${left};--span:${width}">${esc(stageBy(t.stageId)?.name||'')}</button></div></div>`}for(const m of projectMilestones(pid)){const idx=dayDiff(iso(start),m.dueDate);if(idx<0||idx>=days)continue;html+=`<div class="tl-row milestone-row"><div class="tl-label">◆ ${esc(m.title)}</div><div class="tl-track">${dates.map(()=>'<span></span>').join('')}<button class="tl-milestone" data-project-open="${pid}" style="--start:${idx+1}">◆</button></div></div>`}}
  html+='</div>';el.innerHTML=html;el.querySelectorAll('[data-tlnav]').forEach(b=>b.onclick=()=>{const n=Number(b.dataset.tlnav);timelineStart=n===0?new Date():new Date(timelineStart);if(n===0)timelineStart.setDate(timelineStart.getDate()-3);else timelineStart.setDate(timelineStart.getDate()+n);renderTimeline(el,items)});el.querySelectorAll('[data-task]').forEach(b=>b.onclick=()=>{selectedTaskId=b.dataset.task;selectedProjectId=null;renderInspector()});el.querySelectorAll('[data-project-open]').forEach(b=>b.onclick=()=>{selectedProjectId=b.dataset.projectOpen;selectedTaskId=null;renderInspector()})
}

function renderHQ(main){
  if(!supportsWebGL())return renderHQFallback(main);
  main.innerHTML=`<div class="hq-shell"><div class="hq-canvas" id="hqCanvas"></div><div class="hq-toolbar"><button class="btn active" data-hqmode="select">Выбор</button><button class="btn" data-hqmode="connect">Связать</button><button class="btn" id="fitHQ">Показать всё</button><button class="btn ${scope==='critical'?'active':''}" id="criticalHQ">Критический путь</button></div><div class="hq-legend"><div class="legend-row"><span class="legend-line" style="background:#ff5c63"></span> блокирует</div><div class="legend-row"><span class="legend-line" style="background:#6fa8ff"></span> зависит</div><div class="legend-row"><span class="legend-line" style="background:#ffc857"></span> согласование</div></div><div class="hq-help">Тяните фон · колесо / pinch — масштаб · карточки можно перемещать</div></div>`;
  try{hq=new HQView(document.querySelector('#hqCanvas'),{onSelect:taskId=>{selectedTaskId=taskId;selectedProjectId=null;renderInspector()},onOpen:taskId=>{selectedTaskId=taskId;selectedProjectId=null;renderInspector()},onMove:(taskId,pos)=>{const t=taskBy(taskId);if(t){t.position=pos;scheduleSave()}},onCreateRelation:(a,b)=>addRelation(a,b,'blocks')});renderHQData();main.querySelectorAll('[data-hqmode]').forEach(b=>b.onclick=()=>{main.querySelectorAll('[data-hqmode]').forEach(x=>x.classList.remove('active'));b.classList.add('active');hq.setMode(b.dataset.hqmode)});main.querySelector('#fitHQ').onclick=()=>hq.fit();main.querySelector('#criticalHQ').onclick=()=>{scope=scope==='critical'?'all':'critical';renderAll(false)};setTimeout(()=>hq.fit(),100)}catch(e){console.warn('3D view unavailable',e);renderHQFallback(main)}
}
function renderHQFallback(main){const items=filteredTasks(),ids=new Set(items.map(t=>t.id)),rels=state.relations.filter(r=>ids.has(r.sourceId)&&ids.has(r.targetId));main.innerHTML=`<div class="main-scroll relation-fallback"><div class="page-head"><div><div class="eyebrow">Упрощённый режим</div><h1>Связи задач</h1><p>На этом устройстве 3D недоступно. Все зависимости остаются доступны в списке.</p></div><button class="btn" data-try-3d>Проверить 3D снова</button></div><div class="relation-projects">${state.projects.filter(p=>!p.archived&&(currentProject==='all'||p.id===currentProject)).map(p=>`<section class="relation-project"><h2>${esc(p.name)}</h2>${items.filter(t=>t.projectId===p.id).map(t=>`<button data-task="${t.id}" class="relation-task"><b>${esc(t.title)}</b>${taskStatusChip(t)}<small>${esc(t.assignee||'Без ответственного')} · ${fmtDate(t.dueDate)}</small></button>`).join('')||'<div class="home-empty">Нет задач</div>'}</section>`).join('')}</div><section class="relation-list"><h2>Зависимости</h2>${rels.map(r=>`<button data-task="${r.sourceId}"><b>${esc(taskBy(r.sourceId)?.title||'Задача')}</b><span>${esc(REL_TYPES.find(x=>x[0]===r.type)?.[1]||r.type).toLowerCase()} →</span><b>${esc(taskBy(r.targetId)?.title||'Задача')}</b></button>`).join('')||'<div class="home-empty">Связей пока нет</div>'}</section></div>`;main.querySelectorAll('[data-task]').forEach(x=>x.onclick=()=>{selectedTaskId=x.dataset.task;selectedProjectId=null;renderInspector()});main.querySelector('[data-try-3d]').onclick=()=>renderHQ(main)}
function renderHQData(){if(!hq)return;const tasks=filteredTasks().map(t=>({...t,status:effectiveStatus(t)})),ids=new Set(tasks.map(t=>t.id)),projects=currentProject==='all'||currentProject==='inbox'?state.projects:state.projects.filter(p=>p.id===currentProject);hq.setData({projects,tasks,relations:state.relations.filter(r=>ids.has(r.sourceId)&&ids.has(r.targetId))});if(selectedTaskId&&ids.has(selectedTaskId))hq.select(selectedTaskId)}

function renderInspector(){const el=document.querySelector('#inspector');if(!el)return;updateUrl();if(selectedTaskId)return renderTaskInspector(el,taskBy(selectedTaskId));if(selectedProjectId)return renderProjectInspector(el,projectBy(selectedProjectId));el.className='inspector empty';el.innerHTML='<div><b>Выберите задачу или проект</b><p>Здесь появятся детали, этапы, вехи и зависимости.</p></div>'}
function renderTaskInspector(el,t){if(!t){selectedTaskId=null;return renderInspector()}el.className='inspector';const rels=state.relations.filter(r=>r.sourceId===t.id||r.targetId===t.id), blockers=autoBlockers(t),stages=projectStages(t.projectId);el.innerHTML=`<div class="inspector-inner"><div class="inspector-head"><div><div class="eyebrow">${esc(projectBy(t.projectId)?.name||'Входящие')}</div><h2>${esc(t.title)}</h2></div><button class="icon-btn close-inspector" id="closeInspector">×</button></div>${blockers.length?`<div class="auto-block-banner"><b>Автоматически заблокирована</b><span>Сначала завершите: ${blockers.map(x=>esc(x.title)).join(', ')}</span></div>`:''}<div class="field"><label>Название</label><input id="iTitle" value="${esc(t.title)}"></div><div class="field"><label>Описание</label><textarea id="iDesc">${esc(t.description||'')}</textarea></div><div class="grid2"><div class="field"><label>Статус</label><select id="iStatus">${STATUS.map(([v,n])=>`<option value="${v}" ${t.status===v?'selected':''}>${n}</option>`).join('')}</select></div><div class="field"><label>Приоритет</label><select id="iPriority">${PRIORITY.map(([v,n])=>`<option value="${v}" ${t.priority===v?'selected':''}>${n}</option>`).join('')}</select></div></div><div class="grid2"><div class="field"><label>Начало</label><input type="date" id="iStart" value="${esc(t.startDate||'')}"></div><div class="field"><label>Срок</label><input type="date" id="iDue" value="${esc(t.dueDate||'')}"></div></div><div class="field"><label>Ответственный</label><input id="iAssignee" value="${esc(t.assignee||'')}"></div><div class="field"><label>Проект</label><select id="iProject"><option value="">Входящие</option>${state.projects.map(p=>`<option value="${p.id}" ${t.projectId===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select></div><div class="field"><label>Этап</label><select id="iStage"><option value="">Без этапа</option>${stages.map(s=>`<option value="${s.id}" ${t.stageId===s.id?'selected':''}>${esc(s.name)}</option>`).join('')}</select></div><div class="field"><label>Прогресс · ${t.progress||0}%</label><input type="range" min="0" max="100" step="5" id="iProgress" value="${t.progress||0}"></div><div class="ins-section"><h3>Чек-лист</h3>${(t.checklist||[]).map((c,i)=>`<label class="check-row"><input type="checkbox" data-check="${i}" ${c.done?'checked':''}><span>${esc(c.text)}</span></label>`).join('')||'<div class="task-sub">Пока пусто</div>'}<div class="add-check"><input id="newCheck" placeholder="Добавить пункт"><button class="btn" id="addCheck">+</button></div></div><div class="ins-section"><h3>Зависимости</h3>${rels.map(r=>{const other=taskBy(r.sourceId===t.id?r.targetId:r.sourceId);return`<div class="relation"><div>${esc(other?.title||'Удалённая задача')}<br><small>${REL_TYPES.find(x=>x[0]===r.type)?.[1]||r.type}</small></div><button class="icon-btn" data-delrel="${r.id}">×</button></div>`}).join('')||'<div class="task-sub">Связей пока нет</div>'}<button class="btn" id="addRelationBtn" style="margin-top:8px">+ Добавить зависимость</button></div><div class="ins-section"><button class="danger-btn" id="deleteTask">Удалить задачу</button></div></div>`;
  const bind=(q,key,evt='change',map=v=>v)=>el.querySelector(q)?.addEventListener(evt,e=>updateTask(t.id,{[key]:map(e.target.value)}));bind('#iTitle','title','change');bind('#iDesc','description','change');bind('#iStatus','status');bind('#iPriority','priority');bind('#iStart','startDate');bind('#iDue','dueDate');bind('#iAssignee','assignee','change');el.querySelector('#iProject').onchange=e=>{const pid=e.target.value;updateTask(t.id,{projectId:pid,stageId:projectStages(pid)[0]?.id||''})};bind('#iStage','stageId');bind('#iProgress','progress','input',Number);el.querySelectorAll('[data-check]').forEach(x=>x.onchange=()=>{t.checklist[Number(x.dataset.check)].done=x.checked;scheduleSave()});el.querySelector('#addCheck').onclick=()=>{const inp=el.querySelector('#newCheck');if(!inp.value.trim())return;t.checklist.push({text:inp.value.trim(),done:false});scheduleSave();renderInspector()};el.querySelectorAll('[data-delrel]').forEach(x=>x.onclick=()=>{state.relations=state.relations.filter(r=>r.id!==x.dataset.delrel);scheduleSave();renderInspector();renderMain()});el.querySelector('#addRelationBtn').onclick=()=>openRelationModal(t.id);el.querySelector('#deleteTask').onclick=()=>deleteTask(t.id);el.querySelector('#closeInspector')?.addEventListener('click',()=>{selectedTaskId=null;renderInspector()})
}
function renderProjectInspector(el,p){if(!p){selectedProjectId=null;return renderInspector()}el.className='inspector';const stages=projectStages(p.id),ms=projectMilestones(p.id),tasks=projectTasks(p.id),critical=criticalPath(p.id).map(taskBy).filter(Boolean);el.innerHTML=`<div class="inspector-inner"><div class="inspector-head"><div><div class="eyebrow">Проект</div><h2>${esc(p.name)}</h2></div><button class="icon-btn close-inspector" id="closeInspector" aria-label="Закрыть">×</button></div><div class="project-health"><div><strong>${projectProgress(p.id)}%</strong><span>готовность</span></div><div><strong>${tasks.length}</strong><span>${word(tasks.length,'задача','задачи','задач')}</span></div><div><strong>${projectRiskCount(p.id)}</strong><span>${word(projectRiskCount(p.id),'риск','риска','рисков')}</span></div></div><div class="field"><label>Название</label><input id="pName" value="${esc(p.name)}"></div><div class="field"><label>Цель и результат</label><textarea id="pDesc">${esc(p.description||'')}</textarea></div><div class="field"><label>Руководитель</label><input id="pOwner" value="${esc(p.owner||'')}"></div><div class="field"><label>Участники через запятую</label><input id="pMembers" value="${esc((p.members||[]).join(', '))}"></div><div class="grid2"><div class="field"><label>Начало</label><input type="date" id="pStart" value="${esc(p.startDate||'')}"></div><div class="field"><label>Дедлайн</label><input type="date" id="pDue" value="${esc(p.dueDate||'')}"></div></div><div class="ins-section"><div class="section-head"><h3>Этапы</h3><button class="btn mini" id="addStage">+ Этап</button></div>${stages.map((s,i)=>`<div class="stage-row"><span><b>${i+1}</b>${esc(s.name)}</span><small>${tasks.filter(t=>t.stageId===s.id).length} ${word(tasks.filter(t=>t.stageId===s.id).length,'задача','задачи','задач')}</small></div>`).join('')||'<div class="task-sub">Нет этапов</div>'}</div><div class="ins-section"><div class="section-head"><h3>Вехи</h3><button class="btn mini" id="addMilestone">+ Веха</button></div>${ms.map(m=>`<label class="milestone-row-ins"><input type="checkbox" data-msdone="${m.id}" ${m.done?'checked':''}><span><b>${esc(m.title)}</b><small>${fmtLong(m.dueDate)}</small></span><button class="icon-btn" aria-label="Удалить веху" data-delms="${m.id}">×</button></label>`).join('')||'<div class="task-sub">Нет вех</div>'}</div><div class="ins-section"><h3>Критический путь</h3>${critical.length?`<div class="critical-chain">${critical.map((t,i)=>`<button data-task="${t.id}">${i+1}. ${esc(t.title)}</button>`).join('<span>→</span>')}</div>`:'<div class="task-sub">Недостаточно зависимостей для расчёта</div>'}</div><div class="ins-section project-actions"><button class="btn" id="duplicateProject">Создать копию</button><button class="btn" id="archiveProject">${p.archived?'Вернуть из архива':'Архивировать'}</button><button class="danger-btn" id="deleteProject">Удалить проект</button></div></div>`;
  const upd=(key,val)=>{const next={...p,[key]:val};if(next.startDate&&next.dueDate&&next.dueDate<next.startDate){toast('Дедлайн не может быть раньше даты начала');renderInspector();return}p[key]=val;p.updatedAt=new Date().toISOString();scheduleSave();renderSidebar();renderMain()};['Name','Desc','Owner','Start','Due'].forEach(s=>el.querySelector(`#p${s}`)?.addEventListener('change',e=>upd({Name:'name',Desc:'description',Owner:'owner',Start:'startDate',Due:'dueDate'}[s],e.target.value)));el.querySelector('#pMembers').onchange=e=>upd('members',e.target.value.split(',').map(x=>x.trim()).filter(Boolean));el.querySelector('#addStage').onclick=()=>openStageModal(p.id);el.querySelector('#addMilestone').onclick=()=>openMilestoneModal(p.id);el.querySelectorAll('[data-msdone]').forEach(x=>x.onchange=()=>{const m=state.milestones.find(m=>m.id===x.dataset.msdone);if(m)m.done=x.checked;scheduleSave()});el.querySelectorAll('[data-delms]').forEach(x=>x.onclick=e=>{e.preventDefault();state.milestones=state.milestones.filter(m=>m.id!==x.dataset.delms);scheduleSave();renderProjectInspector(el,p);renderMain()});el.querySelectorAll('[data-task]').forEach(x=>x.onclick=()=>{selectedTaskId=x.dataset.task;selectedProjectId=null;renderInspector();hq?.focus?.(x.dataset.task)});el.querySelector('#duplicateProject').onclick=()=>duplicateProject(p.id);el.querySelector('#archiveProject').onclick=()=>{p.archived=!p.archived;if(p.archived&&currentProject===p.id)currentProject='all';selectedProjectId=null;scheduleSave();renderAll(false);toast(p.archived?'Проект перемещён в архив':'Проект возвращён')};el.querySelector('#deleteProject').onclick=()=>deleteProject(p.id);el.querySelector('#closeInspector')?.addEventListener('click',()=>{selectedProjectId=null;renderInspector()})
}

function modal(content){document.querySelector('.modal-backdrop')?.remove();const b=document.createElement('div');b.className='modal-backdrop';b.innerHTML=`<div class="modal" role="dialog" aria-modal="true">${content}</div>`;document.body.appendChild(b);b.onclick=e=>{if(e.target===b)b.remove()};b.querySelectorAll('.field').forEach((f,i)=>{const label=f.querySelector('label'),control=f.querySelector('input,textarea,select');if(label&&control){control.id||=`modalField${i}`;label.htmlFor=control.id}});return b}
function openQuickModal(){const b=modal(`<h2>Быстро во Входящие</h2><p>Только мысль или поручение. Проект, срок и ответственного можно назначить позже.</p><div class="field"><label>Что нужно сделать?</label><input id="qTitle" autofocus placeholder="Например: уточнить площадку у партнёра"></div><div class="modal-actions"><button class="btn ghost" data-close>Отмена</button><button class="btn primary" id="qSave">Добавить</button></div>`);const save=()=>{const title=b.querySelector('#qTitle').value.trim();if(!title)return;addTask({title},{quick:true});b.remove()};b.querySelector('#qSave').onclick=save;b.querySelector('#qTitle').onkeydown=e=>{if(e.key==='Enter')save()};b.querySelector('[data-close]').onclick=()=>b.remove();setTimeout(()=>b.querySelector('#qTitle').focus(),0)}
function openTaskModal(){const defaultProject=currentProject!=='all'&&currentProject!=='inbox'?currentProject:state.projects[0]?.id||'';const b=modal(`<h2>Новая задача</h2><p>Минимум полей сейчас — детали можно заполнить после создания.</p><div class="field"><label>Название</label><input id="mTitle" autofocus></div><div class="grid2"><div class="field"><label>Проект</label><select id="mProject"><option value="">Входящие</option>${state.projects.map(p=>`<option value="${p.id}" ${p.id===defaultProject?'selected':''}>${esc(p.name)}</option>`).join('')}</select></div><div class="field"><label>Срок</label><input id="mDue" type="date"></div></div><div class="field"><label>Ответственный</label><input id="mAssignee"></div><div class="modal-actions"><button class="btn ghost" data-close>Отмена</button><button class="btn primary" id="mSave">Создать</button></div>`);b.querySelector('#mSave').onclick=()=>{addTask({title:b.querySelector('#mTitle').value.trim()||'Новая задача',projectId:b.querySelector('#mProject').value,dueDate:b.querySelector('#mDue').value,assignee:b.querySelector('#mAssignee').value});b.remove()};b.querySelector('[data-close]').onclick=()=>b.remove();setTimeout(()=>b.querySelector('#mTitle').focus(),0)}
function openOrgModal(){const b=modal(`<h2>Пространства</h2><p class="data-note">Переименуйте рабочие области или добавьте новую. Пространство с проектами удалить нельзя.</p><div class="org-editor">${state.organizations.map(o=>`<div class="org-edit-row"><span class="dot" style="background:${o.color||COLORS[0]}"></span><input aria-label="Название пространства" data-org-name="${o.id}" value="${esc(o.name)}"><button class="icon-btn" aria-label="Удалить пространство" data-org-delete="${o.id}">×</button></div>`).join('')}</div><div class="field"><label>Новое пространство</label><input id="oName" placeholder="Название"></div><div class="form-error" data-error role="alert"></div><div class="modal-actions"><button class="btn ghost" data-close>Отмена</button><button class="btn primary" id="oSave">Сохранить</button></div>`);b.querySelectorAll('[data-org-delete]').forEach(btn=>btn.onclick=()=>{const oid=btn.dataset.orgDelete;if(state.projects.some(p=>p.orgId===oid)){b.querySelector('[data-error]').textContent='Сначала перенесите или удалите проекты из этого пространства.';return}if(state.organizations.length===1){b.querySelector('[data-error]').textContent='Нужно оставить хотя бы одно пространство.';return}if(!confirm('Удалить пустое пространство?'))return;state.organizations=state.organizations.filter(o=>o.id!==oid);scheduleSave();b.remove();renderAll(true);openOrgModal()});b.querySelector('#oSave').onclick=()=>{b.querySelectorAll('[data-org-name]').forEach(inp=>{const org=state.organizations.find(o=>o.id===inp.dataset.orgName),name=inp.value.trim();if(org&&name)org.name=name});const name=b.querySelector('#oName').value.trim();if(name)state.organizations.push({id:id(),name,color:COLORS[state.organizations.length%COLORS.length]});scheduleSave();b.remove();renderAll(true);toast('Пространства сохранены')};b.querySelector('[data-close]').onclick=()=>b.remove()}
function openProjectModal(){
  const b=modal(`<div class="wizard-head"><div><div class="eyebrow">Новый проект</div><h2>Соберите рабочую основу</h2></div><div class="wizard-progress"><i class="active">1</i><i>2</i><i>3</i></div></div><section class="wizard-step active" data-step="1"><div class="field"><label>Название проекта</label><input id="prName" autofocus placeholder="Например: Молодёжный форум"></div><div class="field"><label>Цель и ожидаемый результат</label><textarea id="prDesc" placeholder="Что должно измениться или быть готово"></textarea></div><div class="field"><label>Пространство</label><select id="prOrg">${state.organizations.map(o=>`<option value="${o.id}">${esc(o.name)}</option>`).join('')}</select></div><div class="grid2"><div class="field"><label>Начало</label><input type="date" id="prStart"></div><div class="field"><label>Дедлайн</label><input type="date" id="prDue"></div></div></section><section class="wizard-step" data-step="2"><div class="field"><label>Руководитель</label><input id="prOwner" placeholder="Имя"></div><div class="field"><label>Участники через запятую</label><input id="prMembers" placeholder="Алия, Мария, Алексей"></div><div class="field"><label>Этапы — каждый с новой строки</label><textarea id="prStages">Подготовка\nРеализация\nЗавершение</textarea></div></section><section class="wizard-step" data-step="3"><div class="field"><label>Первые задачи — каждая с новой строки</label><textarea id="prTasks" placeholder="Утвердить концепцию\nСобрать команду"></textarea></div><div class="field"><label>Первая контрольная точка</label><input id="prMilestone" placeholder="Например: Концепция утверждена"></div><div class="field"><label>Дата контрольной точки</label><input type="date" id="prMilestoneDue"></div><div class="wizard-review">После создания все поля можно изменить в карточке проекта.</div></section><div class="form-error" data-error role="alert"></div><div class="modal-actions wizard-actions"><button class="btn ghost" data-close>Отмена</button><button class="btn" data-prev hidden>Назад</button><button class="btn primary" data-next>Далее</button><button class="btn primary" data-create hidden>Создать проект</button></div>`);
  let step=1;const show=()=>{b.querySelectorAll('[data-step]').forEach(x=>x.classList.toggle('active',Number(x.dataset.step)===step));b.querySelectorAll('.wizard-progress i').forEach((x,i)=>x.classList.toggle('active',i<step));b.querySelector('[data-prev]').hidden=step===1;b.querySelector('[data-next]').hidden=step===3;b.querySelector('[data-create]').hidden=step!==3;b.querySelector('[data-error]').textContent=''};const validFirst=()=>{const name=b.querySelector('#prName').value.trim(),start=b.querySelector('#prStart').value,due=b.querySelector('#prDue').value;if(!name)return'Укажите название проекта';if(start&&due&&due<start)return'Дедлайн не может быть раньше даты начала';return''};b.querySelector('[data-next]').onclick=()=>{const error=step===1?validFirst():'';if(error){b.querySelector('[data-error]').textContent=error;return}step=Math.min(3,step+1);show()};b.querySelector('[data-prev]').onclick=()=>{step=Math.max(1,step-1);show()};b.querySelector('[data-close]').onclick=()=>b.remove();b.querySelector('[data-create]').onclick=()=>{const error=validFirst();if(error){step=1;show();b.querySelector('[data-error]').textContent=error;return}const pid=id(),stageNames=b.querySelector('#prStages').value.split(/\n+/).map(x=>x.trim()).filter(Boolean),names=stageNames.length?stageNames:['Подготовка','Реализация','Завершение'],stages=names.map((name,i)=>({id:id(),projectId:pid,name,order:i+1})),owner=b.querySelector('#prOwner').value.trim(),members=b.querySelector('#prMembers').value.split(',').map(x=>x.trim()).filter(Boolean);state.projects.push({id:pid,orgId:b.querySelector('#prOrg').value,name:b.querySelector('#prName').value.trim(),status:'active',archived:false,color:COLORS[state.projects.length%COLORS.length],description:b.querySelector('#prDesc').value.trim(),owner,members,startDate:b.querySelector('#prStart').value,dueDate:b.querySelector('#prDue').value});state.stages.push(...stages);const taskNames=b.querySelector('#prTasks').value.split(/\n+/).map(x=>x.trim()).filter(Boolean);taskNames.forEach(title=>state.tasks.push({id:id(),title,description:'',projectId:pid,stageId:stages[0]?.id||'',status:'planned',priority:'medium',startDate:'',dueDate:'',assignee:owner,progress:0,checklist:[],position:null,inbox:false,createdAt:new Date().toISOString(),updatedAt:new Date().toISOString()}));const milestone=b.querySelector('#prMilestone').value.trim();if(milestone)state.milestones.push({id:id(),projectId:pid,stageId:stages[0]?.id||'',title:milestone,dueDate:b.querySelector('#prMilestoneDue').value,done:false});state.meta.demo=false;currentProject=pid;scope='all';selectedProjectId=pid;selectedTaskId=null;scheduleSave();b.remove();renderAll(true);toast('Проект создан')};setTimeout(()=>b.querySelector('#prName').focus(),0)
}
function blankWorkspace(){const org=id();return normalizeState({version:5,meta:{demo:false,createdAt:new Date().toISOString()},organizations:[{id:org,name:'Рабочие проекты',color:COLORS[0]}],projects:[],stages:[],milestones:[],tasks:[],relations:[]})}
function startClean(){if(!confirm('Удалить демонстрационные проекты и начать с чистого листа?'))return;state=blankWorkspace();currentProject='all';scope='all';search='';selectedTaskId=null;selectedProjectId=null;scheduleSave();renderAll(true);openProjectModal()}
function exportWorkspace(){const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`living-project-hq-${todayISO()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('Резервная копия сохранена')}
function openDataModal(){const archived=state.projects.filter(p=>p.archived);const b=modal(`<h2>Данные и резервная копия</h2><p class="data-note">Проекты хранятся в этом браузере. Сохраните резервную копию перед очисткой данных или сменой устройства.</p><div class="data-actions"><button class="btn primary" data-export>Скачать копию</button><label class="btn file-btn">Загрузить копию<input type="file" accept="application/json,.json" data-import></label></div>${archived.length?`<div class="ins-section"><h3>Архив</h3>${archived.map(p=>`<button class="archive-row" data-restore="${p.id}">${esc(p.name)}<span>Восстановить</span></button>`).join('')}</div>`:''}<div class="modal-actions"><button class="btn ghost" data-close>Закрыть</button></div>`);b.querySelector('[data-export]').onclick=exportWorkspace;b.querySelector('[data-import]').onchange=e=>{const file=e.target.files?.[0];if(!file)return;const reader=new FileReader;reader.onload=()=>{try{const incoming=JSON.parse(reader.result);if(!incoming||!Array.isArray(incoming.projects)||!Array.isArray(incoming.tasks))throw new Error;state=normalizeState(incoming);currentProject='all';scope='all';search='';selectedTaskId=null;selectedProjectId=null;scheduleSave();b.remove();renderAll(true);toast('Резервная копия загружена')}catch{b.querySelector('.data-note').textContent='Файл не похож на резервную копию Living Project HQ.'}};reader.readAsText(file)};b.querySelectorAll('[data-restore]').forEach(x=>x.onclick=()=>{const p=projectBy(x.dataset.restore);if(p)p.archived=false;scheduleSave();b.remove();renderAll(true);toast('Проект восстановлен')});b.querySelector('[data-close]').onclick=()=>b.remove()}
function openMobileMenu(){const b=modal(`<h2>Меню</h2><div class="mobile-action-list"><button class="btn primary" data-project>+ Новый проект</button><button class="btn" data-inbox>+ Во Входящие</button><button class="btn" data-data>Данные и архив</button><button class="btn" data-risks>Показать риски</button><button class="btn" data-all>Все проекты</button></div><div class="modal-actions"><button class="btn ghost" data-close>Закрыть</button></div>`);b.querySelector('[data-project]').onclick=()=>{b.remove();openProjectModal()};b.querySelector('[data-inbox]').onclick=()=>{b.remove();openQuickModal()};b.querySelector('[data-data]').onclick=()=>{b.remove();openDataModal()};b.querySelector('[data-risks]').onclick=()=>{b.remove();scope='risks';setView('list')};b.querySelector('[data-all]').onclick=()=>{b.remove();scope='all';currentProject='all';setView('home')};b.querySelector('[data-close]').onclick=()=>b.remove()}
function openStageModal(projectId){const b=modal(`<h2>Новый этап</h2><div class="field"><label>Название</label><input id="sName" autofocus placeholder="Например: Закупки"></div><div class="modal-actions"><button class="btn ghost" data-close>Отмена</button><button class="btn primary" id="sSave">Добавить</button></div>`);b.querySelector('#sSave').onclick=()=>{const name=b.querySelector('#sName').value.trim();if(!name)return;state.stages.push({id:id(),projectId,name,order:projectStages(projectId).length+1});scheduleSave();b.remove();renderInspector();renderMain()};b.querySelector('[data-close]').onclick=()=>b.remove()}
function openMilestoneModal(projectId){const stages=projectStages(projectId);const b=modal(`<h2>Новая веха</h2><div class="field"><label>Название</label><input id="msTitle" autofocus placeholder="Например: Программа утверждена"></div><div class="grid2"><div class="field"><label>Дата</label><input type="date" id="msDue"></div><div class="field"><label>Этап</label><select id="msStage"><option value="">Без этапа</option>${stages.map(s=>`<option value="${s.id}">${esc(s.name)}</option>`).join('')}</select></div></div><div class="modal-actions"><button class="btn ghost" data-close>Отмена</button><button class="btn primary" id="msSave">Добавить</button></div>`);b.querySelector('#msSave').onclick=()=>{const title=b.querySelector('#msTitle').value.trim();if(!title)return;state.milestones.push({id:id(),projectId,stageId:b.querySelector('#msStage').value,title,dueDate:b.querySelector('#msDue').value,done:false});scheduleSave();b.remove();renderInspector();renderMain()};b.querySelector('[data-close]').onclick=()=>b.remove()}
function openRelationModal(sourceId){const options=state.tasks.filter(t=>t.id!==sourceId).map(t=>`<option value="${t.id}">${esc(t.title)} — ${esc(projectBy(t.projectId)?.name||'Входящие')}</option>`).join('');const b=modal(`<h2>Добавить зависимость</h2><div class="field"><label>Связать с задачей</label><select id="rTask">${options}</select></div><div class="field"><label>Тип</label><select id="rType">${REL_TYPES.map(([v,n])=>`<option value="${v}">${n}</option>`).join('')}</select></div><div class="modal-actions"><button class="btn ghost" data-close>Отмена</button><button class="btn primary" id="rSave">Связать</button></div>`);b.querySelector('#rSave').onclick=()=>{addRelation(sourceId,b.querySelector('#rTask').value,b.querySelector('#rType').value);b.remove()};b.querySelector('[data-close]').onclick=()=>b.remove()}

function renderAll(rebuild=true){if(rebuild)shell();renderSidebar();renderMain();renderInspector();updateUrl()}
addEventListener('keydown',e=>{if(e.key==='Escape'){const m=document.querySelector('.modal-backdrop');if(m){m.remove();return}}if((e.ctrlKey||e.metaKey)&&e.key==='Enter'){e.preventDefault();openQuickModal()}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();document.querySelector('#search')?.focus()}});
addEventListener('living-hq:board-closed',()=>{if(view==='board')setView('home')});
addEventListener('beforeunload',()=>{persist()});
renderAll(true);
